from typing import List

class Solution:
    def findReplaceString(self, s: str, indices: List[int], sources: List[str], targets: List[str]) -> str:
        ops = sorted(zip(indices, sources, targets), reverse=True)
        res = list(s)
        for idx, src, tgt in ops:
            if s[idx:idx + len(src)] == src:
                res[idx:idx + len(src)] = list(tgt)
        return "".join(res)

class Solution {
public:
    string findReplaceString(string s, vector<int>& indices, vector<string>& sources, vector<string>& targets) {
        int k = indices.size();
        vector<int> order(k);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) { return indices[a] > indices[b]; });
        for (int idx_i : order) {
            int idx = indices[idx_i];
            const string& src = sources[idx_i];
            const string& tgt = targets[idx_i];
            if (s.substr(idx, src.length()) == src) {
                s = s.substr(0, idx) + tgt + s.substr(idx + src.length());
            }
        }
        return s;
    }
};

class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        int k = indices.length;
        Integer[] order = new Integer[k];
        for (int i = 0; i < k; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(indices[b], indices[a]));
        StringBuilder sb = new StringBuilder(s);
        for (int idxI : order) {
            int idx = indices[idxI];
            String src = sources[idxI];
            String tgt = targets[idxI];
            if (sb.substring(idx, idx + src.length()).equals(src)) {
                sb.replace(idx, idx + src.length(), tgt);
            }
        }
        return sb.toString();
    }
}

var findReplaceString = function(s, indices, sources, targets) {
    const k = indices.length;
    const ops = indices.map((idx, i) => [idx, sources[i], targets[i]]);
    ops.sort((a, b) => b[0] - a[0]);
    let str = s;
    for (const [idx, src, tgt] of ops) {
        if (str.slice(idx, idx + src.length) === src) {
            str = str.slice(0, idx) + tgt + str.slice(idx + src.length);
        }
    }
    return str;
};
